\NewDocumentCommand{\drawFENboard}{m}{%
    \setchessboard{
        showmover=false,
        pgfstyle=border,
        borderwidth=0.05cm,
        labelleft=true,
        labelbottom=true,
        showmover=true
    }
    \fenboard{#1}
    \chessboard
}

