/**
 * Bubble Sort Algorithm Implementation
 * 
 * Time Complexity: O(n²) in worst and average case, O(n) in best case
 * Space Complexity: O(1) - sorts in place
 * 
 * The algorithm repeatedly steps through the list, compares adjacent elements
 * and swaps them if they are in the wrong order. The pass through the list
 * is repeated until the list is sorted.
 */

/**
 * Validates the input array according to specified constraints
 * @param {Array} arr - The array to validate
 * @throws {Error} If validation fails
 */
function validateInput(arr) {
    // Check if input is an array
    if (!Array.isArray(arr)) {
        throw new Error('Input must be an array');
    }

    // Check array length constraint (max 100 elements)
    if (arr.length > 100) {
        throw new Error('Array length cannot exceed 100 elements');
    }

    // Check if array is empty
    if (arr.length === 0) {
        throw new Error('Array cannot be empty');
    }

    // Validate each element
    for (let i = 0; i < arr.length; i++) {
        const element = arr[i];

        // Check if element is a number
        if (typeof element !== 'number' || isNaN(element)) {
            throw new Error(`Element at index ${i} is not a valid number: ${element}`);
        }

        // Check if element is an integer
        if (!Number.isInteger(element)) {
            throw new Error(`Element at index ${i} is not an integer: ${element}`);
        }

        // Check value range constraint (-10,000 to 10,000)
        if (element < -10000 || element > 10000) {
            throw new Error(`Element at index ${i} is out of range [-10000, 10000]: ${element}`);
        }
    }
}

/**
 * Implements the Bubble Sort algorithm to sort an array in ascending order
 * @param {number[]} arr - Array of integers to sort
 * @returns {number[]} - New sorted array (original array is not modified)
 * @throws {Error} If input validation fails
 */
function bubbleSort(arr) {
    try {
        // Validate input
        validateInput(arr);

        // Create a copy of the array to avoid modifying the original
        const sortedArray = [...arr];
        const n = sortedArray.length;

        console.log(`Starting Bubble Sort on array of ${n} elements...`);
        console.log(`Original array: [${arr.join(', ')}]`);

        let swapCount = 0;
        let comparisons = 0;

        // Outer loop: controls the number of passes
        // After each pass, the largest unsorted element "bubbles up" to its correct position
        for (let i = 0; i < n - 1; i++) {
            let swapped = false; // Flag to optimize for already sorted arrays

            // Inner loop: compares adjacent elements
            // Reduces the range each time since the last i elements are already sorted
            for (let j = 0; j < n - i - 1; j++) {
                comparisons++;

                // Compare adjacent elements
                if (sortedArray[j] > sortedArray[j + 1]) {
                    // Swap elements if they are in wrong order
                    [sortedArray[j], sortedArray[j + 1]] = [sortedArray[j + 1], sortedArray[j]];
                    swapped = true;
                    swapCount++;
                }
            }

            // If no swapping occurred in this pass, array is already sorted
            // This optimization reduces best-case time complexity to O(n)
            if (!swapped) {
                console.log(`Array sorted after ${i + 1} passes (early termination)`);
                break;
            }
        }

        console.log(`Sorting completed!`);
        console.log(`Total comparisons: ${comparisons}`);
        console.log(`Total swaps: ${swapCount}`);
        console.log(`Sorted array: [${sortedArray.join(', ')}]`);

        return sortedArray;

    } catch (error) {
        console.error('Bubble Sort Error:', error.message);
        throw error;
    }
}

